-- Run AFTER V2 schema.sql. Additive migration: preserves existing students and results.
-- Review a backup before running. This migration is intended to run ONCE.
alter table public.profiles drop constraint if exists profiles_role_check;
alter table public.profiles add constraint profiles_role_check check(role in ('admin','teacher','parent'));
alter table public.invitations drop constraint if exists invitations_role_check;
alter table public.invitations add constraint invitations_role_check check(role in ('admin','teacher','parent'));
create or replace function public.is_staff(a uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.profiles where id=auth.uid() and academy_id=a and role in ('admin','teacher'))$$;
create table public.branches(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,name text not null,address text default '',phone text default '',created_at timestamptz default now(),unique(id,academy_id));
create table public.admissions(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,branch_id uuid references public.branches(id),applicant_name text not null,class_name text not null,guardian_name text not null,phone text default '',notes text default '',created_at timestamptz default now());
create table public.timetable(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,branch_id uuid references public.branches(id),class_name text not null,subject text not null,teacher_name text default '',weekday text not null,starts_at text not null,ends_at text not null,room text default '',created_at timestamptz default now());
create table public.expenses(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,branch_id uuid references public.branches(id),title text not null,category text default '',amount numeric not null check(amount>=0),date date not null,created_at timestamptz default now());
create table public.salaries(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,branch_id uuid references public.branches(id),teacher_name text not null,month text not null check(month ~ '^\d{4}-\d{2}$'),amount numeric not null check(amount>=0),paid numeric not null default 0 check(paid>=0 and paid<=amount),created_at timestamptz default now());
create table public.calendar_events(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,branch_id uuid references public.branches(id),title text not null,event_date date not null,event_type text default '',description text default '',created_at timestamptz default now());
create table public.syllabus_units(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,branch_id uuid references public.branches(id),class_name text not null,subject text not null,chapter text not null,sequence integer not null default 1,status text default 'Planned',created_at timestamptz default now());
create table public.questions(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,branch_id uuid references public.branches(id),class_name text not null,subject text not null,chapter text default '',slo_code text default '',kind text not null check(lower(kind) in ('mcq','short','long')),difficulty text not null default 'Medium',question text not null,options text default '',answer text default '',marks numeric not null check(marks>0),created_at timestamptz default now());
create table public.parent_students(id uuid primary key default gen_random_uuid(),academy_id uuid not null references public.academies(id) on delete cascade,student_id uuid not null,parent_email text not null,created_at timestamptz default now(),unique(student_id,parent_email),foreign key(student_id,academy_id) references public.students(id,academy_id) on delete cascade);
create or replace function public.is_linked_parent(a uuid,s uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.parent_students ps join public.profiles p on p.academy_id=ps.academy_id and lower(p.email)=lower(ps.parent_email) where p.id=auth.uid() and p.role='parent' and ps.academy_id=a and ps.student_id=s and lower(p.email)=lower((select email from auth.users where id=auth.uid())))$$;
create or replace function public.is_parent_academy(a uuid) returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.parent_students ps join public.profiles p on p.academy_id=ps.academy_id and lower(p.email)=lower(ps.parent_email) where p.id=auth.uid() and p.role='parent' and ps.academy_id=a and lower(p.email)=lower((select email from auth.users where id=auth.uid())))$$;
-- Parent account invitation: admins first link an email to a student, then parent signs up with verified email.
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$declare inv record; plink record;begin select * into inv from public.invitations where lower(email)=lower(new.email) order by created_at desc limit 1;select * into plink from public.parent_students where lower(parent_email)=lower(new.email) order by created_at desc limit 1;insert into public.profiles(id,academy_id,email,role) values(new.id,case when plink.id is not null then plink.academy_id else inv.academy_id end,new.email,case when plink.id is not null then 'parent' else coalesce(inv.role,'teacher') end) on conflict(id) do nothing;return new;end$$;
create or replace function public.claim_invitation() returns boolean language plpgsql security definer set search_path=public as $$declare inv record; plink record; email_address text;begin select email into email_address from auth.users where id=auth.uid();if email_address is null then return false;end if;if exists(select 1 from public.profiles where id=auth.uid() and academy_id is not null) then return false;end if;select * into plink from public.parent_students where lower(parent_email)=lower(email_address) order by created_at desc limit 1;if plink.id is not null then update public.profiles set academy_id=plink.academy_id,role='parent' where id=auth.uid();return true;end if;select * into inv from public.invitations where lower(email)=lower(email_address) order by created_at desc limit 1;if inv.id is null then return false;end if;update public.profiles set academy_id=inv.academy_id,role=inv.role where id=auth.uid();return true;end$$;
-- New modules: RLS is enforced on the server, not just hidden in the UI.
do $$declare t text;begin foreach t in array array['branches','admissions','timetable','expenses','salaries','calendar_events','syllabus_units','questions','parent_students'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy staff_read on public.%I for select to authenticated using(public.is_staff(academy_id))',t);execute format('create policy staff_add on public.%I for insert to authenticated with check(public.is_staff(academy_id))',t);execute format('create policy staff_delete on public.%I for delete to authenticated using(public.is_staff(academy_id))',t);end loop;end$$;
-- Financial data and parent grants only academy admins.
drop policy staff_read on public.expenses;drop policy staff_add on public.expenses;drop policy staff_delete on public.expenses;
drop policy staff_read on public.salaries;drop policy staff_add on public.salaries;drop policy staff_delete on public.salaries;
drop policy staff_read on public.parent_students;drop policy staff_add on public.parent_students;drop policy staff_delete on public.parent_students;
drop policy staff_add on public.branches;drop policy staff_delete on public.branches;
do $$declare t text;begin foreach t in array array['expenses','salaries','parent_students'] loop execute format('create policy admin_read on public.%I for select to authenticated using(public.is_academy_admin(academy_id))',t);execute format('create policy admin_add on public.%I for insert to authenticated with check(public.is_academy_admin(academy_id))',t);execute format('create policy admin_delete on public.%I for delete to authenticated using(public.is_academy_admin(academy_id))',t);end loop;end$$;
create policy admin_add on public.branches for insert to authenticated with check(public.is_academy_admin(academy_id));
create policy admin_delete on public.branches for delete to authenticated using(public.is_academy_admin(academy_id));
-- Remove V2 broad academy write privileges, so parent users cannot mutate academic data.
do $$declare t text;begin foreach t in array array['students','exams','marks','attendance','slos','slo_assessments'] loop execute format('drop policy if exists %I on public.%I',t||'_add',t);execute format('drop policy if exists %I on public.%I',t||'_edit',t);execute format('create policy staff_add on public.%I for insert to authenticated with check(public.is_staff(academy_id))',t);execute format('create policy staff_edit on public.%I for update to authenticated using(public.is_staff(academy_id)) with check(public.is_staff(academy_id))',t);end loop;end$$;
-- Restrict reads for parent accounts to their own children; avoid leaking academy-wide data.
drop policy students_read on public.students;
create policy students_read on public.students for select to authenticated using(public.is_staff(academy_id) or public.is_linked_parent(academy_id,id));
drop policy marks_read on public.marks;
create policy marks_read on public.marks for select to authenticated using(public.is_staff(academy_id) or public.is_linked_parent(academy_id,student_id));
drop policy attendance_read on public.attendance;
create policy attendance_read on public.attendance for select to authenticated using(public.is_staff(academy_id) or public.is_linked_parent(academy_id,student_id));
drop policy exams_read on public.exams;
create policy exams_read on public.exams for select to authenticated using(public.is_staff(academy_id) or (public.is_parent_academy(academy_id) and exists(select 1 from public.marks m where m.exam_id=exams.id and public.is_linked_parent(m.academy_id,m.student_id))));
drop policy profile_read on public.profiles;
create policy profile_read on public.profiles for select to authenticated using(id=auth.uid() or (public.is_staff(academy_id) and academy_id=public.my_academy()));
-- Existing academies need to be readable by linked parents.
drop policy academy_read on public.academies;
create policy academy_read on public.academies for select to authenticated using(id=public.my_academy());
-- No cross-academy branch assignments.
create or replace function public.check_v3_branch() returns trigger language plpgsql set search_path=public as $$begin if new.branch_id is not null and not exists(select 1 from public.branches where id=new.branch_id and academy_id=new.academy_id) then raise exception 'Branch must belong to the same academy';end if;return new;end$$;
do $$declare t text;begin foreach t in array array['admissions','timetable','expenses','salaries','calendar_events','syllabus_units','questions'] loop execute format('create trigger check_branch before insert or update on public.%I for each row execute function public.check_v3_branch()',t);end loop;end$$;
